begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
 ('17000000-0000-0000-0000-000000000001','onboarding-test@novacorp.test','{"first_name":"Nina","last_name":"Test"}'),
 ('17000000-0000-0000-0000-000000000002','onboarding-empty@novacorp.test','{}'),
 ('17000000-0000-0000-0000-000000000003',null,'{}');
select is((select count(*)::integer from employee_onboardings where employee_id='17000000-0000-0000-0000-000000000001'),1,'nouveau profil : un accueil automatiquement mis en file');
select is((select jsonb_array_length(checklist) from employee_onboardings where employee_id='17000000-0000-0000-0000-000000000001'),6,'checklist de six etapes');
update profiles set first_name='Nina actualisee',role='manager' where id='17000000-0000-0000-0000-000000000001';
select is((select count(*)::integer from employee_onboardings where employee_id='17000000-0000-0000-0000-000000000001'),1,'mise a jour et changement de role sans doublon');
set local role authenticated;
select throws_ok($q$select * from employee_onboardings$q$,'42501',null,'file inaccessible au navigateur');
select throws_ok($q$select claim_employee_onboarding()$q$,'42501',null,'reservation reservee au backend');
select throws_ok($q$select finish_employee_onboarding(gen_random_uuid(),gen_random_uuid(),true)$q$,'42501',null,'acquittement reserve au backend');
reset role;
create temporary table onboarding_mail(data jsonb);
grant all on onboarding_mail to service_role;
set local role service_role;
insert into onboarding_mail select claim_employee_onboarding('17000000-0000-0000-0000-000000000001');
select is((select data->>'to' from onboarding_mail),'onboarding-test@novacorp.test','email adresse au nouveau collegue');
select matches((select data->>'subject' from onboarding_mail),'Bienvenue','objet de bienvenue');
select matches((select data->>'text' from onboarding_mail),'Nina actualisee','prenom actuel au moment de l envoi');
select matches((select data->>'text' from onboarding_mail),'Checklist du premier jour','checklist dans le meme email');
select is((select regexp_count(data->>'text','\[ \]') from onboarding_mail),6,'six cases a cocher dans le message');
select matches((select data->>'text' from onboarding_mail),'localhost:3000/connexion','lien vers la connexion');
select is((claim_employee_onboarding('17000000-0000-0000-0000-000000000001')->>'claimed')::boolean,false,'reservation exclusive');
select is((select status::text from employee_onboardings where employee_id='17000000-0000-0000-0000-000000000002'),'queued','reservation ciblee isole les autres employes');
select is((finish_employee_onboarding((select (data->>'notification_id')::uuid from onboarding_mail),gen_random_uuid(),true)->>'recorded')::boolean,false,'mauvais jeton refuse');
select is((finish_employee_onboarding((select (data->>'notification_id')::uuid from onboarding_mail),(select (data->>'lease_token')::uuid from onboarding_mail),false)->>'recorded')::boolean,true,'echec SMTP trace');
select is((select status::text from employee_onboardings where employee_id='17000000-0000-0000-0000-000000000001'),'failed','etat SMTP conserve');
select is((claim_employee_onboarding('17000000-0000-0000-0000-000000000001')->>'claimed')::boolean,false,'temporisation avant reprise');
update employee_onboardings set next_attempt_at=now() where employee_id='17000000-0000-0000-0000-000000000001';
update onboarding_mail set data=claim_employee_onboarding('17000000-0000-0000-0000-000000000001');
select is((select attempts from employee_onboardings where employee_id='17000000-0000-0000-0000-000000000001'),2,'seconde tentative apres echec');
select is((finish_employee_onboarding((select (data->>'notification_id')::uuid from onboarding_mail),(select (data->>'lease_token')::uuid from onboarding_mail),true,'fixture-mail-id')->>'recorded')::boolean,true,'envoi acquitte');
select is((finish_employee_onboarding((select (data->>'notification_id')::uuid from onboarding_mail),(select (data->>'lease_token')::uuid from onboarding_mail),true)->>'replayed')::boolean,true,'acquittement idempotent');
select is((claim_employee_onboarding('17000000-0000-0000-0000-000000000001')->>'claimed')::boolean,false,'aucune nouvelle livraison apres succes');
update onboarding_mail set data=claim_employee_onboarding('17000000-0000-0000-0000-000000000002');
select matches((select data->>'text' from onboarding_mail),'^Bonjour,','accueil generique si prenom absent');
update employee_onboardings set lease_until=now()-interval '1 second' where employee_id='17000000-0000-0000-0000-000000000002';
select is((claim_employee_onboarding('17000000-0000-0000-0000-000000000002')->>'claimed')::boolean,true,'reprise d une reservation expiree');
select is((finish_employee_onboarding((select (data->>'notification_id')::uuid from onboarding_mail),(select (data->>'lease_token')::uuid from onboarding_mail),true)->>'recorded')::boolean,false,'ancien jeton invalide apres reprise');
update employee_onboardings set attempts=5,lease_until=now()-interval '1 second' where employee_id='17000000-0000-0000-0000-000000000002';
select is((claim_employee_onboarding('17000000-0000-0000-0000-000000000002')->>'claimed')::boolean,false,'cinquieme reservation expiree abandonnee');
select is((select next_attempt_at::text from employee_onboardings where employee_id='17000000-0000-0000-0000-000000000002'),'infinity','arret des reprises apres cinq tentatives');
select is((claim_employee_onboarding('17000000-0000-0000-0000-000000000003')->>'claimed')::boolean,false,'absence d adresse : aucun envoi');
select is((select next_attempt_at::text from employee_onboardings where employee_id='17000000-0000-0000-0000-000000000003'),'infinity','adresse absente signalee sans boucle infinie');
reset role;
delete from auth.users where id='17000000-0000-0000-0000-000000000003';
select is((select count(*)::integer from employee_onboardings where employee_id='17000000-0000-0000-0000-000000000003'),0,'suppression du compte nettoie son accueil');
select * from finish();
rollback;
